#include <iostream>
#include <string>
using namespace std;

class MutablePoint {
private:
    int x;
    int y;

public:
    MutablePoint(int x, int y) : x(x), y(y) {}

    int getX() { return x; }
    int getY() { return y; }

    void setX(int newX) { x = newX; }
    void setY(int newY) { y = newY; }

    // A thread reading both fields has no guarantee it sees a
    // consistent pair, another thread may be halfway through an update.
    string describe() {
        return "(" + to_string(x) + ", " + to_string(y) + ")";
