Runnable reader = () -> {
    for (int i = 0; i < 1_000_000; i++) {
        String snapshot = shared.describe();
        // Occasionally prints something like (48213, 48200),
        // a pair that never actually existed together on the diagonal.
        if (!isOnDiagonal(snapshot)) {
            System.out.println("Inconsistent read: " + snapshot);
        }
    }
};

new Thread(mover).start();
new Thread(reader).start();

