public final class ImmutablePoint {
    private final int x;
    private final int y;

    public ImmutablePoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() { return x; }
    public int getY() { return y; }

    // Instead of mutating this object, hand back a brand new one.
    public ImmutablePoint moveTo(int newX, int newY) {
        return new ImmutablePoint(newX, newY);
    }

    public String describe() {
        // x and y can never disagree with each other, they were
        // fixed together at construction and can never change again.
        return "(" + x + ", " + y + ")";
    }
}

