#include <iostream>
#include <string>
#include <memory>
#include <thread>
#include <stdexcept>
using namespace std;

shared_ptr<ImmutablePoint> shared = make_shared<ImmutablePoint>(0, 0);

void mover() {
    for (int i = 0; i < 1000000; i++) {
        atomic_store(&shared, make_shared<ImmutablePoint>(i, i));
    }
}

void reader() {
    for (int i = 0; i < 1000000; i++) {
        shared_ptr<ImmutablePoint> snapshot = atomic_load(&shared);
        string s = snapshot->describe();
        // Every single read is guaranteed to be a coordinate pair
        // that genuinely existed together, because the object itself
        // never changes after it is built, only the pointer swaps.
        if (!isOnDiagonal(s)) {
            throw runtime_error("impossible: " + s);
        }
    }
}

int main() {
    thread moverThread(mover);
    thread readerThread(reader);
    moverThread.join();
    readerThread.join();
    return 0;
}

