#include <iostream>
#include <string>
#include <vector>
using namespace std;

class ImmutableOrder {
private:
    const string orderId;
    const vector<string> items;

public:
    ImmutableOrder(const string& orderId, const vector<string>& items)
        // Defensive copy on the way in, the caller's vector can now
        // change freely without affecting this object.
        : orderId(orderId), items(items) {}

    string getOrderId() const { return orderId; }

    vector<string> getItems() const {
        // vector has no built-in immutable wrapper, so a copy is
        // returned here to keep the caller from mutating our internals.
        return items;
    }
};

