public class MutableBalance {
    private long cents;

    public MutableBalance(long cents) { this.cents = cents; }

    public void deposit(long amount) {
        // read, add, write, three separate steps another thread can interleave with
        long current = cents;
        cents = current + amount;
    }

    public void withdraw(long amount) {
        long current = cents;
        cents = current - amount;
    }

    public long getCents() { return cents; }
}

